`timescale 1ns / 1ps
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
// --Function  : 
//		1. use the ISERDESE3 (1to8) primitive, support logic bitslip;
//		2. support 10bit、12bit;
//		3. no channel correction; 
//		4. clk_rxg and clk_rxio are different clock domains. clk_rxg is generated by FPGA MMCM, clk_rxio is output by cmos.
// ------------------------------------------------------------------------------------------------------------------------------------------------------------------------
// --History   :
// --Ver       Date         By              Description
// --1.0       2023.09.11   LTJ             create
// --FH-1      2026.10.02   OpenAI          Remove obsolete CCIO_EN_* IBUFDS parameters for ZU7EV/Vivado 2025.2.
// --FH-2      2026.10.02   OpenAI          Split global/read/write reset handling; per-lane training reset is synchronized
//                                           into the 150 MHz lane domain and FIFO receives separate write/read resets.
// --FH-4      2026.10.02   OpenAI          Mark the explicit 120->150 MHz single-bit synchronizer chains ASYNC_REG so
//                                           Vivado CDC analysis recognizes reset/bitslip/IDELAY-load synchronization.
// --FH-5      2026.10.02   OpenAI          Mark reg_bit_width and IDELAY value synchronizer stages ASYNC_REG.
//                                           Snapshot the synchronized 9-bit IDELAY value only when the synchronized
//                                           load event arrives, so CNTVALUEIN is coherent and stable before LOAD.
// --FH-6      2026-10-03   OpenAI          Add sticky raw-serial activity observation from the ISERDESE3 8-bit
//                                           sample bus for V16 D0/D1 receiver diagnostics.
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------

module iserdes1to10_12(
	// clock
	input					clk_rxg,
	input					clk_rxio,
	input					clk_rxio_d4,
	
	// ctrl
	input                   rst_rxg,            // global reset, synchronous to clk_rxg
	input                   rst_rxio_d4,        // global reset, synchronous to this lane CLKDIV domain
	input					rst_iserdes,		// per-lane soft reset, clk_rxg domain
	input					bitslip,			// 脉宽3个clk_rxg
	input             		idelay_ld,			// 脉宽3个clk_rxg
	input [8:0]      	 	idelay_valuein,
	
	input [1:0]				reg_bit_width,
	//data
	input					dataswap,
	input					datain_ser_p,
	input					datain_ser_n,
	output reg [11:0]		datapar,
	output reg              raw_activity
		
    );
//////////////////////////////////////////////////////////////////////////
// Reset / control synchronization
//
// rst_iserdes is a per-lane soft reset generated in the 120 MHz training
// domain. Synchronize it into this lane's 150 MHz CLKDIV domain. The global
// resets are already synchronized independently by gmax3412_iob_clock.
//////////////////////////////////////////////////////////////////////////
    (* ASYNC_REG = "TRUE", SHREG_EXTRACT = "NO" *) reg rst_iserdes_d4_soft;
    (* ASYNC_REG = "TRUE", SHREG_EXTRACT = "NO" *) reg rst_iserdes_q;
    (* ASYNC_REG = "TRUE", SHREG_EXTRACT = "NO" *) reg rst_iserdes_qq;
    (* ASYNC_REG = "TRUE", SHREG_EXTRACT = "NO" *) reg [1:0] reg_bit_width_q;
    (* ASYNC_REG = "TRUE", SHREG_EXTRACT = "NO" *) reg [1:0] reg_bit_width_qq;

	always @(posedge clk_rxio_d4) begin
        if (rst_rxio_d4) begin
            rst_iserdes_q       <= 1'b1;
            rst_iserdes_qq      <= 1'b1;
            rst_iserdes_d4_soft <= 1'b1;
            reg_bit_width_q     <= 2'd0;
            reg_bit_width_qq    <= 2'd0;
        end else begin
            rst_iserdes_q       <= rst_iserdes;
            rst_iserdes_qq      <= rst_iserdes_q;
            rst_iserdes_d4_soft <= rst_iserdes_qq;
            reg_bit_width_q     <= reg_bit_width;
            reg_bit_width_qq    <= reg_bit_width_q;
        end
	end

    wire rst_lane_d4  = rst_rxio_d4 | rst_iserdes_d4_soft;
    wire rst_lane_rxg = rst_rxg      | rst_iserdes;
	
//////////////////////////////////////////////////////////////////////////
// IBUFDS
//////////////////////////////////////////////////////////////////////////
	wire					datain_ser;
	//wire					datain_ser_t;
	IBUFDS
	IBUFDS_inst (
		.O				(datain_ser),   
		.I				(datain_ser_p), 
		.IB				(datain_ser_n)  
   );	
	
	//assign datain_ser = (dataswap == 1'b0) ? datain_ser_t : ~datain_ser_t;
	
   /***** IDELAY *****/ 
	wire					dataout_idelay;
	
    (* ASYNC_REG = "TRUE", SHREG_EXTRACT = "NO" *) reg [1:0] idelay_ld_sync;
    (* ASYNC_REG = "TRUE", SHREG_EXTRACT = "NO" *) reg idelay_ld_sync_q;
    (* ASYNC_REG = "TRUE", SHREG_EXTRACT = "NO" *) reg idelay_ld_sync_qq;
	reg						idelay_ld_d4;
	
    // idelay_valuein is a data-stable multi-bit CDC: the source holds the value
    // for many clk_rxg cycles around idelay_ld. Two ASYNC_REG stages settle the
    // bus in clk_rxio_d4; a third, ordinary register snapshots the settled bus
    // only when the synchronized load event arrives.
    (* ASYNC_REG = "TRUE", SHREG_EXTRACT = "NO" *) reg [8:0] idelay_valuein_q;
    (* ASYNC_REG = "TRUE", SHREG_EXTRACT = "NO" *) reg [8:0] idelay_valuein_qq;
    reg [8:0] idelay_valuein_d4;
	reg [3:0]				cnt_bitslip;
	reg						bitslip_d4;
	
	always @(posedge clk_rxio_d4) begin
        if (rst_lane_d4) begin
            idelay_ld_sync      <= 2'b00;
            idelay_ld_sync_q    <= 1'b0;
            idelay_ld_sync_qq   <= 1'b0;
            idelay_ld_d4        <= 1'b0;
            idelay_valuein_q    <= 9'd0;
            idelay_valuein_qq   <= 9'd0;
            idelay_valuein_d4   <= 9'd0;
        end else begin
            idelay_ld_sync[0]   <= idelay_ld;
            idelay_ld_sync[1]   <= idelay_ld_sync[0];
            idelay_ld_sync_q    <= idelay_ld_sync[1];
            idelay_ld_sync_qq   <= idelay_ld_sync_q;

            // Synchronize the value continuously, but only commit a new
            // CNTVALUEIN snapshot on the delayed/synchronized load event.
            // Because idelay_ld traverses additional synchronizer stages,
            // idelay_valuein_qq has already settled before this capture.
            idelay_valuein_q  <= idelay_valuein;
            idelay_valuein_qq <= idelay_valuein_q;

            if (idelay_ld_sync_q == 1'b1 && idelay_ld_sync_qq == 1'b0) begin
                idelay_valuein_d4 <= idelay_valuein_qq;
                idelay_ld_d4      <= 1'b1;
            end else begin
                idelay_ld_d4      <= 1'b0;
            end
        end
	end
		
   IDELAYE3 #(
      .CASCADE					("NONE"),            
      .DELAY_FORMAT				("COUNT"),          
      .DELAY_SRC				("IDATAIN"),         
      .DELAY_TYPE				("VAR_LOAD"),        
      .DELAY_VALUE				(0),                
      .IS_CLK_INVERTED			(1'b0),        	 	
      .IS_RST_INVERTED			(1'b0),         	
      .REFCLK_FREQUENCY			(300.0),       		
      .SIM_DEVICE				("ULTRASCALE_PLUS"), 
      .UPDATE_MODE				("ASYNC")           
													
   )
   u_IDELAYE3 (
      .CASC_OUT					(),      			 	
      .CNTVALUEOUT				(), 					
      .DATAOUT					(dataout_idelay),       
      .CASC_IN					(),        			 	
      .CASC_RETURN				(),						
      .CE						(1'b0),                 
      .CLK						(clk_rxio_d4),              
      .CNTVALUEIN				(idelay_valuein_d4),   	
      .DATAIN					(),           		
      .EN_VTC					(1'b0),           	
      .IDATAIN					(datain_ser),       
      .INC						(),                 
      .LOAD						(idelay_ld_d4),             
      .RST						(rst_lane_d4)                 
   );	
//////////////////////////////////////////////////////////////////////////
// ISERDESE3
//////////////////////////////////////////////////////////////////////////	
	wire [7:0]				iserdese3_dout;
	
   ISERDESE3 #(
      .DATA_WIDTH				(8),               
      .FIFO_ENABLE				("FALSE"),         
      .FIFO_SYNC_MODE			("FALSE"),       	
      .IS_CLK_B_INVERTED		(1'b0),       		
      .IS_CLK_INVERTED			(1'b0),        		
      .IS_RST_INVERTED			(1'b0),         	
      .SIM_DEVICE				("ULTRASCALE_PLUS")
													
   )
   ISERDESE3_inst (
      .FIFO_EMPTY				(),          			
      .INTERNAL_DIVCLK			(), 					
														

      .Q						(iserdese3_dout),       
      .CLK						(clk_rxio),             
      .CLKDIV					(clk_rxio_d4),          
      .CLK_B					(~clk_rxio),            
      .D						(dataout_idelay),       
      .FIFO_RD_CLK				(1'b0),       			
      .FIFO_RD_EN				(1'b0),          		
      .RST						(rst_lane_d4)        
   );	
	
//////////////////////////////////////////////////////////////////////////
// V16 raw serial activity monitor
//
// The GMAX training pattern is repetitive, so the parallel 10-bit word can
// legitimately remain constant. Observe the pre-word-alignment ISERDESE3
// 8-bit sample bus instead and latch activity when successive samples differ.
// This flag is diagnostic only; it does not participate in receiver training.
//////////////////////////////////////////////////////////////////////////
	reg [7:0] raw_sample_prev;

	always @(posedge clk_rxio_d4) begin
        if (rst_lane_d4) begin
            raw_sample_prev <= 8'd0;
            raw_activity    <= 1'b0;
        end else begin
            if (iserdese3_dout != raw_sample_prev)
                raw_activity <= 1'b1;
            raw_sample_prev <= iserdese3_dout;
        end
	end

//////////////////////////////////////////////////////////////////////////
// BITSLIP function
//////////////////////////////////////////////////////////////////////////	
    (* ASYNC_REG = "TRUE", SHREG_EXTRACT = "NO" *) reg [1:0] bitslip_sync;
    (* ASYNC_REG = "TRUE", SHREG_EXTRACT = "NO" *) reg bitslip_sync_q;
    (* ASYNC_REG = "TRUE", SHREG_EXTRACT = "NO" *) reg bitslip_sync_qq;
	always @(posedge clk_rxio_d4) begin
        if (rst_lane_d4) begin
            bitslip_sync    <= 2'b00;
            bitslip_sync_q  <= 1'b0;
            bitslip_sync_qq <= 1'b0;
            bitslip_d4      <= 1'b0;
        end else begin
            bitslip_sync[0]    <= bitslip;
            bitslip_sync[1]    <= bitslip_sync[0];
            bitslip_sync_q     <= bitslip_sync[1];
            bitslip_sync_qq    <= bitslip_sync_q;

            if (bitslip_sync_q == 1'b1 && bitslip_sync_qq == 1'b0)
                bitslip_d4 <= 1'b1;
            else
                bitslip_d4 <= 1'b0;
        end
	end
	
	always @(posedge clk_rxio_d4) begin
		if (rst_lane_d4 == 1) begin
			cnt_bitslip			<= 0;
		end
		else begin
			if (bitslip_d4 == 1) begin
				cnt_bitslip		<= cnt_bitslip	+ 1;
			end
		end
	end
	

//	数据拼接	

	reg [7:0]				iserdese3_dout_q;
	reg [7:0]				iserdese3_dout_qq;
	reg [7:0]				iserdese3_dout_shift;
	reg [7:0]				iserdese3_dout_shift_q;
	
	always @(posedge clk_rxio_d4) begin
		if (rst_lane_d4 == 1) begin
			iserdese3_dout_q		<= 8'd0;
			iserdese3_dout_qq		<= 8'd0;
			iserdese3_dout_shift	<= 8'd0;
			iserdese3_dout_shift_q	<= 8'd0;
		end	
		else begin	
			iserdese3_dout_q		<= iserdese3_dout;
			iserdese3_dout_qq		<= iserdese3_dout_q;
			iserdese3_dout_shift_q	<= iserdese3_dout_shift;
			
			case(cnt_bitslip)
				0: iserdese3_dout_shift	<= iserdese3_dout_qq;
				1: iserdese3_dout_shift	<= {iserdese3_dout_q[0]  ,iserdese3_dout_qq[7:1]};
				2: iserdese3_dout_shift	<= {iserdese3_dout_q[1:0],iserdese3_dout_qq[7:2]};
				3: iserdese3_dout_shift	<= {iserdese3_dout_q[2:0],iserdese3_dout_qq[7:3]};
				4: iserdese3_dout_shift	<= {iserdese3_dout_q[3:0],iserdese3_dout_qq[7:4]};
				5: iserdese3_dout_shift	<= {iserdese3_dout_q[4:0],iserdese3_dout_qq[7:5]};
				6: iserdese3_dout_shift	<= {iserdese3_dout_q[5:0],iserdese3_dout_qq[7:6]};
				7: iserdese3_dout_shift	<= {iserdese3_dout_q[6:0],iserdese3_dout_qq[7]};
				8: iserdese3_dout_shift	<= iserdese3_dout_q;
				9: iserdese3_dout_shift	<= {iserdese3_dout[0]  ,iserdese3_dout_q[7:1]};
				10:iserdese3_dout_shift	<= {iserdese3_dout[1:0],iserdese3_dout_q[7:2]};
				11:iserdese3_dout_shift	<= {iserdese3_dout[2:0],iserdese3_dout_q[7:3]};
				12:iserdese3_dout_shift	<= {iserdese3_dout[3:0],iserdese3_dout_q[7:4]}; 
			endcase
		end
	end

	
//	数据拼接	
	reg [2:0]				cnt_data_val;
	
	always @(posedge clk_rxio_d4) begin
		if (rst_lane_d4 == 1) begin
			cnt_data_val	<= 0;
		end
		else begin
			if(reg_bit_width_qq == 0)begin //12bit
				if (cnt_data_val == 2) begin
					cnt_data_val	<= 0;
				end
				else begin
					cnt_data_val	<= cnt_data_val + 1;
				end
			end
			else if(reg_bit_width_qq == 2)begin//10bit
				if(cnt_data_val == 4)begin
					cnt_data_val	<= 0;
				end
				else begin
					cnt_data_val	<= cnt_data_val + 1;
				end
			end
		end
	end
	
	reg						data_val = 0;
	reg [11:0]				data_12b;
	
	always @(posedge clk_rxio_d4) begin		
        if (rst_lane_d4) begin
            data_val <= 1'b0;
            data_12b <= 12'd0;
        end
		else if (reg_bit_width_qq == 0) begin		// 12bit
			case (cnt_data_val)
				0: begin
						data_val		<= 1'b1;
						data_12b	<= {iserdese3_dout_shift[3:0],iserdese3_dout_shift_q};
					end
				1: begin
						data_val		<= 1'b1;
						data_12b	<= {iserdese3_dout_shift,iserdese3_dout_shift_q[7:4]};
					end
				2: begin
						data_val		<= 1'b0;
						data_12b		<= data_12b;
					end
				default:begin
						data_val		<= 1'b0;					
					end
			endcase
		end
		else if (reg_bit_width_qq == 2) begin	// 10bit
			case (cnt_data_val)
				0: begin
					data_val		<= 1'b1;
					data_12b		<= {2'd0,iserdese3_dout_shift[1:0],iserdese3_dout_shift_q};
				end
				1: begin
					data_val		<= 1'b1;
					data_12b		<= {2'd0,iserdese3_dout_shift[3:0],iserdese3_dout_shift_q[7:2]};
				end
				2: begin
					data_val		<= 1'b1;
					data_12b		<= {2'd0,iserdese3_dout_shift[5:0],iserdese3_dout_shift_q[7:4]};
				end
				3: begin
					data_val		<= 1'b1;
					data_12b		<= {2'd0,iserdese3_dout_shift,iserdese3_dout_shift_q[7:6]};
				end
				4: begin
					data_val		<= 1'b0;
					data_12b		<= data_12b;
				end
				default:begin
					data_12b		<= 1'b0;
					end
			endcase
		end
	end

//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------
// Output across clock domains
//		there may be data storage in FIFO due to bitslip. However, since the bit depth of FIFO is 16 bits, bitslip can be effective for 12 times at most 
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------

	wire [11:0] 			datapar_t;
 	reg 					fifo_ren;
	wire [4:0]				rd_data_count;    
	
	FIFO_ICD_W12_D32_RDC u_fifo (
        .wr_rst             (rst_lane_d4),
        .rd_rst             (rst_lane_rxg),
		
		.wr_clk				(clk_rxio_d4),
		.wr_en				(data_val),
		.din				(data_12b),
		
		.rd_clk				(clk_rxg),
		.rd_en				(fifo_ren),
		.dout				(datapar_t),
		.rd_data_count		(rd_data_count),
		
		.full				(),
		.empty				()
	);
 
	always @(posedge clk_rxg) begin
		if (rst_lane_rxg) begin
			fifo_ren		<= 0;
		end
		else begin
			if (rd_data_count >= 7) begin
				fifo_ren			<= 1;
			end
		end
	end
		
   always @(posedge clk_rxg) begin
        if (rst_lane_rxg) begin
            datapar <= 12'd0;
        end
		else if (dataswap == 0) begin
			datapar  		<= datapar_t;
		end
		else begin
			
			if (reg_bit_width == 0) begin		// 12bit
				datapar[0]     <= ~datapar_t[0];
				datapar[1]     <= ~datapar_t[1];
				datapar[2]     <= ~datapar_t[2];
				datapar[3]     <= ~datapar_t[3];
				datapar[4]     <= ~datapar_t[4];
				datapar[5]     <= ~datapar_t[5];
				datapar[6]     <= ~datapar_t[6];
				datapar[7]     <= ~datapar_t[7];
				datapar[8]     <= ~datapar_t[8];
				datapar[9]     <= ~datapar_t[9];
				datapar[10]    <= ~datapar_t[10];
				datapar[11]    <= ~datapar_t[11];
			end
			else begin
				datapar[0]     <= ~datapar_t[0];
				datapar[1]     <= ~datapar_t[1];
				datapar[2]     <= ~datapar_t[2];
				datapar[3]     <= ~datapar_t[3];
				datapar[4]     <= ~datapar_t[4];
				datapar[5]     <= ~datapar_t[5];
				datapar[6]     <= ~datapar_t[6];
				datapar[7]     <= ~datapar_t[7];
				datapar[8]     <= ~datapar_t[8];
				datapar[9]     <= ~datapar_t[9];
				datapar[10]    <= datapar_t[10];
				datapar[11]    <= datapar_t[11];			
			end
		end
   end

      
endmodule
